#!/usr/bin/env python3
"""Evidence-aware coverage dashboard. Document presence is never a completeness pass."""
import argparse,collections,html,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--repo',type=pathlib.Path,required=True);p.add_argument('--canon',type=pathlib.Path);a=p.parse_args();repo=a.repo.resolve();root=(a.canon or repo/'AETHERION_CANON').resolve()
def load(f):return json.loads((root/f).read_text())
entities=load('01_WORLD_BIBLE/ENTITY_CONTRACT.json')['records'];assets=load('10_ASSET_REGISTRY/MASTER_ASSET_REGISTRY.json')['records'];source=load('00_GOVERNANCE/SOURCE_COVERAGE.json')['elements'];cast=json.loads((repo/'CASTABLE_REGISTRY.json').read_text())['castables']
criteria=[('Lore','01_WORLD_BIBLE',[]),('Geography','03_GEOGRAPHY',['Q','AF']),('Architecture','09_ART_DIRECTION',['N','O']),('Leaders','05_FACTIONS_AND_CHARACTERS',['A']),('NPCs','05_FACTIONS_AND_CHARACTERS',['A','I']),('Sorcerers','09_ART_DIRECTION',['K']),('Ninjas','09_ART_DIRECTION',['J']),('Weapons','10_ASSET_REGISTRY',['E','F']),('Armor','10_ASSET_REGISTRY',['G','H']),('Items','10_ASSET_REGISTRY',['L']),('Creatures','12_CREATURES_AND_MOUNTS',['R']),('Bosses','12_CREATURES_AND_MOUNTS',['S']),('Mounts','12_CREATURES_AND_MOUNTS',['T']),('Housing','15_HOUSING',['AD']),('Life skills','14_LIFE_SKILLS_AND_ECONOMY',['M']),('VFX','11_REFERENCE_SHEETS',['W','X','Y']),('Abilities','08_ABILITY_MATRIX',['W']),('Combat animation','11_REFERENCE_SHEETS',['D']),('Environmental interaction','07_GAMEPLAY_SYSTEMS',['AG','AE']),('Music','09_ART_DIRECTION',['AA']),('UI','17_TECHNICAL_ART',['Z']),('Quests','06_NARRATIVE',[]),('Dungeons','04_OATH_DOSSIERS',['O','AE']),('Public events','13_WORLD_EVENTS',['AC']),('PvP','16_PVP_AND_TERRITORY',['V']),('Technical specifications','17_TECHNICAL_ART',['AH'])]
records=[]
for e in entities:
 oath=e['oath_id'];by=[x for x in assets if oath in x.get('oath_ids',[])];sc=next((x for x in source if x['element'].lower()==e['element'].lower()),{})
 for label,directory,categories in criteria:
  docs=sorted(str(x.relative_to(root)) for x in (root/directory).glob('*.md'))
  if directory=='08_ABILITY_MATRIX' and not docs:docs=sorted('08_ABILITY_MATRIX/'+x.name for x in (repo/'AETHERION_CANON/08_ABILITY_MATRIX').glob('*.md'))
  family=[x for x in by if x.get('record_kind')=='production_family_requirement' and x.get('category_id') in categories]
  refs=[x for x in by if x.get('record_kind')=='reference_image' and set(x.get('category_ids',[]))&set(categories)]
  records.append({'id':f'coverage-{oath}-{label.lower().replace(" ","-")}','oath_id':oath,'criterion':label,'canon_status':'PROPOSED','source_ids':['SRC-USER-DIRECTIVE','SRC-GOVERNANCE-PROPOSAL'],'documentation_status':'AUTHORED_REVIEW_REQUIRED' if docs else 'MISSING','documentation_evidence':docs,'documentation_completeness':'Not inferred from file or heading presence; see independent review and open decisions','proposed_family_requirements':len(family),'related_reference_images':len(refs),'reference_ids':[x['id'] for x in refs],'production_status':'NOT_PRODUCTION_VALIDATED','production_validated_count':0,'source_castables_imported':sum(x['proposedAetherion']['oathId']==oath for x in cast) if label=='Abilities' else None,'asset_gap':'Reference images are concept evidence; rigs, meshes, animation, audio, gameplay and target-device approval require their own gates.','dedicated_vfx_series_recovered':sc.get('vfx_sequence',0) if label=='VFX' else None})
d={'schema_version':'1.0.0','canon_status':'PROPOSED','source_ids':['SRC-GOVERNANCE-PROPOSAL','SRC-USER-DIRECTIVE'],'policy':'390 criterion cells separate authored documentation, recovered reference evidence, imported source castables, and production validation. Zero validated means not established by this project validation, not proof no reusable source asset exists. Broad realm overviews can support multiple categories; counts are not additive.','records':records}
out=root/'19_VALIDATION';(out/'CANON_COVERAGE_DASHBOARD.json').write_text(json.dumps(d,indent=2)+'\n')
lines=['# Canon coverage dashboard','','Fifteen Oaths ×26 production criteria. **Authored documentation is not a completeness pass.** All new designs need semantic review and approval; source import tests have separate scoped results.','', '| Oath | Documentation cells with authored evidence | Related original images | Imported castables | Production-validated realm assets |','|---|---:|---:|---:|---:|']
for e in entities:
 o=e['oath_id'];cells=[x for x in records if x['oath_id']==o];n=sum(x['documentation_status']!='MISSING' for x in cells);refs={x['id'] for x in assets if x.get('record_kind')=='reference_image' and o in x.get('oath_ids',[])};cs=sum(x['proposedAetherion']['oathId']==o for x in cast);lines.append(f"| {e['oath_name']} | {n}/26, review required | {len(refs)} | {cs} | 0 established |")
lines+=['','## Read the cells, not just the totals','','[Machine-readable 390-cell dashboard](CANON_COVERAGE_DASHBOARD.json) supplies criterion-level document paths, reference IDs, family requirement counts and explicit unknowns. [Interactive-free accessible table](CANON_COVERAGE_DASHBOARD.html) exposes the same fields.','', '## Gates shared by every realm','','- Founder review of new lore, geography, leaders, chronology, abilities-to-world extensions and consequences.','- Individual reference concept acceptance and resolution of conflicting variants.','- Approved derivative meshes, rigs, clips, audio, shaders and LOD/collision specifications.','- GPU/source-equivalence testing, real target interactions and target-device measurements.','- Production networking/persistence/streaming implementation; schemas and design contracts do not constitute these systems.','- Rights review of third-party assets and dependencies.','', 'See INDEPENDENT_REVIEW.md for semantic findings and their resolution; see CANON_VALIDATION_REPORT.json for automated PASS/FAIL/SKIPPED/HUMAN_REVIEW checks.']
(out/'CANON_COVERAGE_DASHBOARD.md').write_text('\n'.join(lines)+'\n')
rows=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in [r['oath_id'],r['criterion'],r['documentation_status'],r['proposed_family_requirements'],r['related_reference_images'],r['source_castables_imported'] if r['source_castables_imported'] is not None else '—',r['production_status']])+'</tr>' for r in records)
(out/'CANON_COVERAGE_DASHBOARD.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Aetherion coverage</title><style>body{font:16px system-ui;margin:2rem;color:#172033;background:#faf9f6}table{border-collapse:collapse;font-size:.85rem}th,td{padding:.5rem;border:1px solid #bbb;text-align:left}th{position:sticky;top:0;background:#e4e9ee}caption{text-align:left;margin:1rem 0}div{overflow:auto}a{color:#174993}</style><h1>Aetherion production coverage</h1><p>15 Oaths ·26 criteria. Authored documents and reference images are not finished production assets. No game-system, art or GPU validation is implied by coverage.</p><div><table><caption>Criterion-level evidence: proposed families, related references and source imports count different things.</caption><thead><tr><th>Oath</th><th>Criterion</th><th>Documentation</th><th>Proposed families</th><th>Related images</th><th>Imported castables</th><th>Production</th></tr></thead><tbody>'+rows+'</tbody></table></div></html>')
print(f'{len(records)} cells written')
